CREATE OR REPLACE FUNCTION public.load_account_document(p_document_key text)
 RETURNS TABLE(revision bigint, content jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid := auth.uid();
BEGIN
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT revision, content
  INTO revision, content
  FROM account_documents
  WHERE owner = v_owner AND document_key = p_document_key;

  IF NOT FOUND THEN
    revision := 0;
    content := '{}'::jsonb;
  END IF;

  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_device(p_device_id uuid, p_bearer_token_sha256 bytea, p_revoke_if_token_mismatch boolean DEFAULT true)
 RETURNS TABLE(device_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid := auth.uid();
  v_existing registered_devices%ROWTYPE;
BEGIN
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_bearer_token_sha256 IS NULL OR octet_length(p_bearer_token_sha256) = 0 THEN
    RAISE EXCEPTION 'token sha256 required';
  END IF;

  SELECT *
  INTO v_existing
  FROM registered_devices
  WHERE owner = v_owner AND device_id = p_device_id;

  IF NOT FOUND THEN
    INSERT INTO registered_devices (owner, device_id, device_token_sha256, is_revoked, created_at, updated_at)
    VALUES (v_owner, p_device_id, p_bearer_token_sha256, false, now(), now())
    RETURNING registered_devices.device_id INTO device_id;
    RETURN;
  END IF;

  IF v_existing.device_token_sha256 = p_bearer_token_sha256 THEN
    -- Ensure not revoked and bump updated timestamp.
    UPDATE registered_devices
    SET is_revoked = false,
        updated_at = now()
    WHERE owner = v_owner AND device_id = p_device_id;
    device_id := p_device_id;
    RETURN;
  END IF;

  IF p_revoke_if_token_mismatch THEN
    UPDATE registered_devices
    SET device_token_sha256 = p_bearer_token_sha256,
        is_revoked = false,
        updated_at = now()
    WHERE owner = v_owner AND device_id = p_device_id;
    device_id := p_device_id;
    RETURN;
  ELSE
    -- Keep existing token; caller should re-register/revoke on its own.
    RAISE EXCEPTION 'device token mismatch for device_id' USING ERRCODE = 'P0001';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_account_document(p_document_key text, p_expected_revision bigint, p_content jsonb)
 RETURNS TABLE(revision bigint, content jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid := auth.uid();
  v_now timestamptz := now();
  v_existing_revision bigint;
  v_new_revision bigint;
BEGIN
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_content IS NULL THEN
    p_content := '{}'::jsonb;
  END IF;

  SELECT revision
  INTO v_existing_revision
  FROM account_documents
  WHERE owner = v_owner AND document_key = p_document_key;

  IF NOT FOUND THEN
    -- Allow initial creation only if expected_revision is 0.
    IF COALESCE(p_expected_revision, 0) <> 0 THEN
      RAISE EXCEPTION 'conflict: expected_revision % does not match missing doc (server_revision 0)',
        p_expected_revision
        USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO account_documents (owner, document_key, revision, content, created_at, updated_at)
    VALUES (v_owner, p_document_key, 1, p_content, v_now, v_now)
    RETURNING revision, content INTO revision, content;

    RETURN;
  END IF;

  v_new_revision := v_existing_revision;

  -- Compare-and-swap: must match.
  IF v_existing_revision <> p_expected_revision THEN
    -- Return the existing revision/content implicitly via a conflict error.
    RAISE EXCEPTION 'conflict: expected_revision % does not match server_revision %',
      p_expected_revision, v_existing_revision
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE account_documents
  SET revision = revision + 1,
      content = p_content,
      updated_at = v_now
  WHERE owner = v_owner AND document_key = p_document_key
  RETURNING revision, content INTO revision, content;

  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
